export async function loadCurrentLighting({fetcher=fetch,signal}={}){const check=()=>{if(signal?.aborted)throw Error('S9_LIGHT_CANCELLED')};check();const layer=await createLightingCandidate({pins,readBytes:async name=>{check();const response=await fetcher(new URL('lighting-assets/'+name,moduleURL),{signal});if(!response.ok)throw Error('S9_LIGHT_HTTP');const bytes=await response.arrayBuffer();check();return bytes}});try{check();return layer}catch(e){layer.dispose();throw e}}
